// ─── File: SecureConnectDemo.java ───
// This file contains multiple classes for the runnable demo.
// In a real project each class would be in its own file.
package com.bank.connect;

import java.util.*;
import java.util.logging.*;

public class SecureConnectDemo {
    private static final Logger log = Logger.getLogger("RDSSecureConnect");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // DB allows only the transfer-service security group, TLS required.
        RdsConnectionManager db = new RdsConnectionManager(
                "sg-ledger", Set.of("sg-transfer-service"), "prod/nbi-ledger/credentials");

        ConnectionRequest legit = new ConnectionRequest("sg-transfer-service", true, true);
        ConnectionRequest fromInternet = new ConnectionRequest("public", true, false);
        ConnectionRequest noTls = new ConnectionRequest("sg-transfer-service", false, true);

        log.info(() -> "Transfer service connect: " + db.connect(legit));
        log.severe(() -> "Internet connect: " + db.connect(fromInternet));
        log.warning(() -> "No-TLS connect: " + db.connect(noTls));

        // Cross-account: fraud-analytics (account A) reaching ledger (account B).
        CrossAccountAccess cross = new CrossAccountAccess(db);
        log.info(() -> "Cross-account (peering + role + shared secret): "
                + cross.connectFromOtherAccount("sg-fraud-analytics", true, true));
        log.severe(() -> "Cross-account without peering: "
                + cross.connectFromOtherAccount("sg-fraud-analytics", false, true));
    }
}

// ─── Would be in RdsConnectionManager.java ───
class RdsConnectionManager {
    private final String dbSecurityGroup;
    private final Set<String> allowedSourceSgs;
    private final String secretId;
    RdsConnectionManager(String dbSecurityGroup, Set<String> allowedSourceSgs, String secretId) {
        this.dbSecurityGroup = dbSecurityGroup;
        this.allowedSourceSgs = allowedSourceSgs;
        this.secretId = secretId;
    }

    // Enforce: allowed security group + credentials from Secrets Manager + TLS.
    String connect(ConnectionRequest req) {
        if (!allowedSourceSgs.contains(req.sourceSecurityGroup())) {
            return "DENIED — source SG not allowed (private subnet, no public access)";
        }
        if (!req.usesSecretsManager()) {
            return "DENIED — hardcoded credentials rejected; must use " + secretId;
        }
        if (!req.overTls()) {
            return "DENIED — TLS required (sslmode=verify-full)";
        }
        return "CONNECTED — via private endpoint, rotated secret, TLS";
    }

    boolean allows(String sg) { return allowedSourceSgs.contains(sg); }
    String secretId() { return secretId; }
}

// ─── Would be in CrossAccountAccess.java ───
class CrossAccountAccess {
    private final RdsConnectionManager db;
    CrossAccountAccess(RdsConnectionManager db) { this.db = db; }

    // Needs network (peering/PrivateLink) + cross-account role + shared secret.
    String connectFromOtherAccount(String sourceSg, boolean networkPeered, boolean roleAssumed) {
        if (!networkPeered) {
            return "DENIED — no VPC peering/PrivateLink, accounts isolated";
        }
        if (!roleAssumed) {
            return "DENIED — cross-account IAM role not assumed";
        }
        // The DB SG must also allow the peer source SG and the secret must be shared.
        return "CONNECTED — peering up, role assumed, DB SG allows peer, secret shared via resource policy";
    }
}

// ─── Would be in ConnectionRequest.java ───
class ConnectionRequest {
    private final String sourceSecurityGroup;
    private final boolean overTls;
    private final boolean usesSecretsManager;
    ConnectionRequest(String sourceSecurityGroup, boolean overTls, boolean usesSecretsManager) {
        this.sourceSecurityGroup = sourceSecurityGroup;
        this.overTls = overTls;
        this.usesSecretsManager = usesSecretsManager;
    }
    String sourceSecurityGroup() { return sourceSecurityGroup; }
    boolean overTls() { return overTls; }
    boolean usesSecretsManager() { return usesSecretsManager; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
